-- Supply Request workflow (Objective 3): maker-checker flow between Branch, Admin and Logistics.
-- Additive only. Safe to run again: every column/table is "if not exists", constraints are
-- dropped and re-added, and the old->new status mapping only touches rows still in old statuses.

-- 1. Settings (one row): earliest delivery in working days, and the bulk-check threshold.
create table if not exists public."supply_settings" (
  "id" bigint generated by default as identity primary key,
  "supply_lead_time_working_days" smallint not null default 2,
  "bulk_threshold_percent" numeric(6,2) not null default 50,
  "updated_by_user_id" bigint references public."users" ("id") on delete set null,
  "created_at" timestamptz default now(),
  "updated_at" timestamptz default now(),
  constraint "supply_settings_lead_time_check" check ("supply_lead_time_working_days" between 1 and 10),
  constraint "supply_settings_bulk_check" check ("bulk_threshold_percent" >= 0)
);
alter table public."supply_settings" enable row level security;
-- No row is seeded (the MySQL importer needs empty tables): the API uses 2 working days and 50% until Admin saves the settings.

-- 2. The request: urgency, bulk reason, contact, backorder link, decisions and reasons.
alter table public."supply_requests" add column if not exists "urgency" text not null default 'normal';
alter table public."supply_requests" add column if not exists "urgency_reason" text;
alter table public."supply_requests" add column if not exists "bulk_reason" text;
alter table public."supply_requests" add column if not exists "contact_number" text;
alter table public."supply_requests" add column if not exists "parent_request_id" bigint;
alter table public."supply_requests" add column if not exists "backorder_seq" smallint;
alter table public."supply_requests" add column if not exists "submitted_at" timestamptz;
alter table public."supply_requests" add column if not exists "status_changed_at" timestamptz;
alter table public."supply_requests" add column if not exists "fulfillment_type" text;
alter table public."supply_requests" add column if not exists "fulfillment_reason" text;
alter table public."supply_requests" add column if not exists "fulfillment_decided_by_user_id" bigint;
alter table public."supply_requests" add column if not exists "fulfillment_decided_at" timestamptz;
alter table public."supply_requests" add column if not exists "expected_restock_date" date;
alter table public."supply_requests" add column if not exists "restock_revision_count" integer not null default 0;
alter table public."supply_requests" add column if not exists "on_hold_at" timestamptz;
alter table public."supply_requests" add column if not exists "confirmed_delivery_date" date;
alter table public."supply_requests" add column if not exists "scheduled_by_user_id" bigint;
alter table public."supply_requests" add column if not exists "scheduled_at" timestamptz;
alter table public."supply_requests" add column if not exists "returned_reason" text;
alter table public."supply_requests" add column if not exists "returned_by_user_id" bigint;
alter table public."supply_requests" add column if not exists "returned_at" timestamptz;
alter table public."supply_requests" add column if not exists "rejected_reason" text;
alter table public."supply_requests" add column if not exists "rejected_by_user_id" bigint;
alter table public."supply_requests" add column if not exists "rejected_at" timestamptz;
alter table public."supply_requests" add column if not exists "cancelled_reason" text;
alter table public."supply_requests" add column if not exists "cancelled_by_user_id" bigint;
alter table public."supply_requests" add column if not exists "cancelled_at" timestamptz;
alter table public."supply_requests" add column if not exists "discrepancy_action" text;
alter table public."supply_requests" add column if not exists "discrepancy_remarks" text;
alter table public."supply_requests" add column if not exists "discrepancy_resolved_by_user_id" bigint;
alter table public."supply_requests" add column if not exists "discrepancy_resolved_at" timestamptz;
alter table public."supply_requests" add column if not exists "receipt_reminded_at" timestamptz;
alter table public."supply_requests" add column if not exists "reservation_incomplete" boolean not null default false;

alter table public."supply_requests" drop constraint if exists "supply_requests_urgency_check";
alter table public."supply_requests" add constraint "supply_requests_urgency_check" check ("urgency" in ('normal', 'urgent', 'critical'));
alter table public."supply_requests" drop constraint if exists "supply_requests_fulfillment_type_check";
alter table public."supply_requests" add constraint "supply_requests_fulfillment_type_check"
  check ("fulfillment_type" is null or "fulfillment_type" in ('full', 'hold', 'partial_ship_now', 'partial_consolidated'));
alter table public."supply_requests" drop constraint if exists "supply_requests_discrepancy_action_check";
alter table public."supply_requests" add constraint "supply_requests_discrepancy_action_check"
  check ("discrepancy_action" is null or "discrepancy_action" in ('accept_loss', 'logistics_investigation', 'branch_rerequest'));
alter table public."supply_requests" drop constraint if exists "supply_requests_parent_request_id_fkey";
alter table public."supply_requests" add constraint "supply_requests_parent_request_id_fkey" foreign key ("parent_request_id") references public."supply_requests" ("id") on delete restrict;
alter table public."supply_requests" drop constraint if exists "supply_requests_fulfillment_decided_by_fkey";
alter table public."supply_requests" add constraint "supply_requests_fulfillment_decided_by_fkey" foreign key ("fulfillment_decided_by_user_id") references public."users" ("id") on delete set null;
alter table public."supply_requests" drop constraint if exists "supply_requests_scheduled_by_fkey";
alter table public."supply_requests" add constraint "supply_requests_scheduled_by_fkey" foreign key ("scheduled_by_user_id") references public."users" ("id") on delete set null;
alter table public."supply_requests" drop constraint if exists "supply_requests_returned_by_fkey";
alter table public."supply_requests" add constraint "supply_requests_returned_by_fkey" foreign key ("returned_by_user_id") references public."users" ("id") on delete set null;
alter table public."supply_requests" drop constraint if exists "supply_requests_rejected_by_fkey";
alter table public."supply_requests" add constraint "supply_requests_rejected_by_fkey" foreign key ("rejected_by_user_id") references public."users" ("id") on delete set null;
alter table public."supply_requests" drop constraint if exists "supply_requests_cancelled_by_fkey";
alter table public."supply_requests" add constraint "supply_requests_cancelled_by_fkey" foreign key ("cancelled_by_user_id") references public."users" ("id") on delete set null;
alter table public."supply_requests" drop constraint if exists "supply_requests_discrepancy_resolved_by_fkey";
alter table public."supply_requests" add constraint "supply_requests_discrepancy_resolved_by_fkey" foreign key ("discrepancy_resolved_by_user_id") references public."users" ("id") on delete set null;
create index if not exists "supply_requests_parent_idx" on public."supply_requests" ("parent_request_id");
create index if not exists "supply_requests_status_idx" on public."supply_requests" ("status", "location_id");

-- 3. Items: the fulfillment decision, what was prepared, and what the branch received.
alter table public."supply_request_items" add column if not exists "quantity_available" numeric(14,2);
alter table public."supply_request_items" add column if not exists "quantity_unavailable" numeric(14,2);
alter table public."supply_request_items" add column if not exists "expected_restock_date" date;
alter table public."supply_request_items" add column if not exists "quantity_endorsed" numeric(14,2);
alter table public."supply_request_items" add column if not exists "quantity_prepared" numeric(14,2);
alter table public."supply_request_items" add column if not exists "received_good" numeric(14,2);
alter table public."supply_request_items" add column if not exists "received_damaged" numeric(14,2);
alter table public."supply_request_items" add column if not exists "received_short" numeric(14,2);
alter table public."supply_request_items" add column if not exists "damage_reason" text;
alter table public."supply_request_items" add column if not exists "short_reason" text;
alter table public."supply_request_items" add column if not exists "suggested_quantity" numeric(14,3);
alter table public."supply_request_items" add column if not exists "over_bulk" boolean not null default false;

-- 4. Warehouse reservations: reserved at endorsement, consumed at dispatch, released on cancel/reject.
create table if not exists public."supply_reservations" (
  "id" bigint generated by default as identity primary key,
  "supply_request_id" bigint not null references public."supply_requests" ("id") on delete restrict,
  "supply_request_item_id" bigint not null references public."supply_request_items" ("id") on delete restrict,
  "product_id" bigint not null references public."products" ("id") on delete restrict,
  "location_id" bigint not null references public."franchise_locations" ("id") on delete restrict,
  "quantity" numeric(14,2) not null,
  "status" text not null default 'active',
  "created_by_user_id" bigint references public."users" ("id") on delete set null,
  "consumed_at" timestamptz,
  "released_at" timestamptz,
  "created_at" timestamptz default now(),
  "updated_at" timestamptz default now(),
  constraint "supply_reservations_quantity_check" check ("quantity" > 0),
  constraint "supply_reservations_status_check" check ("status" in ('active', 'consumed', 'released'))
);
alter table public."supply_reservations" enable row level security;
create index if not exists "supply_reservations_product_idx" on public."supply_reservations" ("product_id", "status");
create index if not exists "supply_reservations_request_idx" on public."supply_reservations" ("supply_request_id", "status");

-- 5. Shortage reports from Logistics: a pending sub-state that Admin must answer.
create table if not exists public."supply_shortage_reports" (
  "id" bigint generated by default as identity primary key,
  "supply_request_id" bigint not null references public."supply_requests" ("id") on delete restrict,
  "stage" text not null,
  "reason" text not null,
  "items" jsonb not null default '[]'::jsonb,
  "status" text not null default 'pending',
  "reported_by_user_id" bigint references public."users" ("id") on delete set null,
  "decided_by_user_id" bigint references public."users" ("id") on delete set null,
  "decided_at" timestamptz,
  "created_at" timestamptz default now(),
  "updated_at" timestamptz default now(),
  constraint "supply_shortage_reports_status_check" check ("status" in ('pending', 'decided'))
);
alter table public."supply_shortage_reports" enable row level security;
create index if not exists "supply_shortage_reports_request_idx" on public."supply_shortage_reports" ("supply_request_id", "status");

-- 6. Date changes now come from Logistics and are decided by Admin (older rows were proposed by Admin).
alter table public."supply_request_date_revisions" add column if not exists "proposed_by_role" text not null default 'admin';
alter table public."supply_request_date_revisions" add column if not exists "reason" text;
alter table public."supply_request_date_revisions" add column if not exists "decided_by_user_id" bigint;
alter table public."supply_request_date_revisions" add column if not exists "decided_at" timestamptz;
alter table public."supply_request_date_revisions" add column if not exists "decision_reason" text;
alter table public."supply_request_date_revisions" drop constraint if exists "supply_request_date_revisions_decided_by_fkey";
alter table public."supply_request_date_revisions" add constraint "supply_request_date_revisions_decided_by_fkey" foreign key ("decided_by_user_id") references public."users" ("id") on delete set null;

-- 7. Delivery: driver and vehicle at dispatch; the POD with the actual delivery time.
alter table public."deliveries" add column if not exists "driver_name" text;
alter table public."deliveries" add column if not exists "driver_contact" text;
alter table public."deliveries" add column if not exists "plate_number" text;
alter table public."deliveries" add column if not exists "departed_at" timestamptz;
alter table public."deliveries" add column if not exists "eta_at" timestamptz;
alter table public."deliveries" add column if not exists "actual_delivered_at" timestamptz;
alter table public."deliveries" add column if not exists "pod_encoded_by_user_id" bigint;
alter table public."deliveries" add column if not exists "pod_encoded_at" timestamptz;
alter table public."deliveries" add column if not exists "pod_document_id" bigint;
alter table public."deliveries" drop constraint if exists "deliveries_pod_encoded_by_fkey";
alter table public."deliveries" add constraint "deliveries_pod_encoded_by_fkey" foreign key ("pod_encoded_by_user_id") references public."users" ("id") on delete set null;

-- 8. Audit trail: action, role and attached file on every step; append-only like the applicant history.
alter table public."supply_request_status_histories" add column if not exists "action" text;
alter table public."supply_request_status_histories" add column if not exists "actor_role" text;
alter table public."supply_request_status_histories" add column if not exists "document_id" bigint;
drop trigger if exists "supply_request_status_histories_append_only" on public."supply_request_status_histories";
create trigger "supply_request_status_histories_append_only" before update on public."supply_request_status_histories"
  for each row execute function public.refuse_history_update();

-- 9. Existing requests: map the old statuses (only rows still in an old status are touched).
update public."supply_requests" set "status_changed_at" = coalesce("updated_at", "created_at", now()) where "status_changed_at" is null;
update public."supply_requests" set "submitted_at" = "created_at" where "submitted_at" is null and "status" <> 'draft';

-- Items already past endorsement carry their endorsed (and, once prepared, prepared) quantity.
update public."supply_request_items" si set "quantity_endorsed" = si."quantity_requested"
from public."supply_requests" sr
where sr."id" = si."supply_request_id" and si."quantity_endorsed" is null
  and sr."status" in ('endorsed', 'preparing', 'dispatched', 'delivered', 'completed');
update public."supply_request_items" si set "quantity_prepared" = si."quantity_requested"
from public."supply_requests" sr
where sr."id" = si."supply_request_id" and si."quantity_prepared" is null and sr."status" in ('dispatched', 'delivered', 'completed');

-- Old endorsed -> scheduled, reserving warehouse stock; a reservation that cannot be made in
-- full is flagged so Logistics sees it and can report a shortage.
do $$
declare
  wh bigint;
  req record;
  item record;
  free numeric;
  take numeric;
  short boolean;
begin
  select id into wh from public."franchise_locations" where "type" = 'warehouse' and "is_active" order by id limit 1;
  for req in select * from public."supply_requests" where "status" = 'endorsed' order by id loop
    short := false;
    for item in select * from public."supply_request_items" where "supply_request_id" = req.id order by id loop
      free := coalesce((select i."current_stock" from public."inventories" i where i."location_id" = wh and i."product_id" = item."product_id"), 0)
            - coalesce((select sum(r."quantity") from public."supply_reservations" r where r."product_id" = item."product_id" and r."status" = 'active'), 0);
      take := least(item."quantity_requested", greatest(free, 0));
      if take > 0 and wh is not null then
        insert into public."supply_reservations" ("supply_request_id", "supply_request_item_id", "product_id", "location_id", "quantity", "status")
        values (req.id, item.id, item."product_id", wh, take, 'active');
      end if;
      if take < item."quantity_requested" then short := true; end if;
      update public."supply_request_items" set "quantity_available" = take, "quantity_unavailable" = item."quantity_requested" - take where id = item.id;
    end loop;
    update public."supply_requests" set
      "status" = 'scheduled', "fulfillment_type" = 'full', "reservation_incomplete" = short,
      "confirmed_delivery_date" = coalesce((select r."revised_delivery_date" from public."supply_request_date_revisions" r
        where r."supply_request_id" = req.id and r."status" = 'confirmed' order by r.id desc limit 1), req."target_delivery_date"),
      "scheduled_at" = coalesce(req."endorsed_at", now()), "status_changed_at" = now()
    where id = req.id;
    insert into public."supply_request_status_histories" ("supply_request_id", "from_status", "to_status", "action", "actor_role", "remarks", "payload")
    values (req.id, 'endorsed', 'scheduled', 'migrated', 'system',
      case when short then 'Reservation incomplete at migration. Logistics: use Report Shortage.' else 'Moved to Scheduled by the new supply workflow; warehouse stock reserved.' end,
      jsonb_build_object('reservation_incomplete', short));
  end loop;
end $$;

-- Old delivered -> completed (the branch was already credited under the old flow).
insert into public."supply_request_status_histories" ("supply_request_id", "from_status", "to_status", "action", "actor_role", "remarks")
select id, 'delivered', 'completed', 'migrated', 'system', 'Closed by migration: received under the previous workflow.'
from public."supply_requests" where "status" = 'delivered';
update public."supply_requests" set "status" = 'completed', "status_changed_at" = now(),
  "completed_at" = coalesce("completed_at", (select d."delivered_at" from public."deliveries" d where d."supply_request_id" = supply_requests.id limit 1), now())
where "status" = 'delivered';

-- Admin-proposed date revisions still pending have no counterpart in the new flow.
update public."supply_request_date_revisions" set "status" = 'superseded', "decision_reason" = 'Superseded by the new supply workflow.'
where "status" = 'pending' and "proposed_by_role" = 'admin';

-- 10. Every status is one of the new workflow's.
alter table public."supply_requests" drop constraint if exists "supply_requests_status_check";
alter table public."supply_requests" add constraint "supply_requests_status_check" check ("status" in (
  'draft', 'submitted', 'under_review', 'returned', 'waiting_logistics', 'scheduled', 'on_hold', 'preparing', 'dispatched',
  'delivered', 'discrepancy_review', 'completed', 'completed_with_discrepancy', 'rejected', 'cancelled'
));
